import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"45、【萃】 坤下兑上","description":"周易阐真 - 45、【萃】 坤下兑上","frontmatter":{"title":"45、【萃】 坤下兑上","description":"周易阐真 - 45、【萃】 坤下兑上"},"headers":[],"relativePath":"zh/classics/chanzhen/046.md","filePath":"zh/classics/chanzhen/046.md"}'),s={name:"zh/classics/chanzhen/046.md"};function n(c,a,i,o,h,l){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：萃，聚也。顺以说，刚中而应，故聚也。王假有庙，致孝享也。利见大人亨，聚以正也。用大牲吉，利有攸往，顺天命也。观其所聚，而天地万物之情可见矣。</p></blockquote><h1 id="_45、【萃】-坤下兑上" tabindex="-1">45、【萃】 坤下兑上 <a class="header-anchor" href="#_45、【萃】-坤下兑上" aria-label="Permalink to “45、【萃】 坤下兑上”">​</a></h1><p>初六：有孚不终，乃乱乃萃。若号，一握为笑，勿恤，往无咎。</p><p>六二：引吉，无咎。孚乃利用禴。</p><p>六三：萃如，嗟如，无攸利。往无咎，小吝。</p><p>九四：大吉，无咎。</p><p>九五：萃有位，无咎。匪孚，元永贞，悔亡。</p><p>上六：赍咨涕洟，无咎。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：泽上于地，萃。君子以除戎器，戒不虞。</p><p>萃者，聚也。上兑泽，下坤地，是泽上于地也。泽在地而上于地，凡地上之物，莫不得其滋润，而皆荣旺焉。但泽水有限，润物不久，物有时荣旺，即有时不荣旺，此萃之象也。</p><p>君子有见于此，知修道者，至于五行攒簇，还元返本，一切后天之物，皆顺听其命；若不知防危虑险，久之聚者仍散，得而失之患必不能免。以是除戎器以戒其不虞焉。除者，修制也；戎器者，慧器也。慧器者，即神明默运之功。当先天凝聚，己不为后天所伤，然必消尽历劫轮回种子，方能性命坚固。倘有一点滓质未尽，日久后天又发，先天仍散。此戒备之功不可缺。能除戎器、戒不虞，则主人公常在，命宝不伤，久而五行混化，形神俱妙，与道合真，永为金刚不坏之物矣。保萃之道贵乎哉!</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>假，音格。握，乙解切。禴，音约。赍，音咨。洟，音夷。</p><p>萃者，聚也。卦德上兑悦，下坤顺，我顺人而人即悦，故谓萃。此攒簇药物之卦，承上夬卦而来。夬者，以阳而决阴也。决阴之道，乃丹头到手以后之事。当丹头未得，若无攒簇药物之功，而丹头不结。但人自有生以后，性相近而习相远，忘其本真，逐于外假，心神不定，精气耗散，非可遽能收摄，是贵乎以顺为体，以和为用，循序渐进，火候不差，专心致志，愈久愈力，自然已失者而可还，已去者而可返，犹如王者假神有庙也。</p><p>祖先为人之根本，忘其根本，则不孝而非人，王者假神在庙，所以使人人皆知有根本之当报耳。人之本来天真，如祖先之根本也。人之弃真认假，如忘祖先之根本也。人能收敛神气，修持性命，复还本来天真，如不忘祖先之根本也。王者之不忘根本，能以聚天下之人心。修道者之不忘根本，能以攒性命之大药。但此不忘根本之事，须要大人行之，非一切不知性命之小人所能行，是以利见于大人亨也。</p><p>盖大人者，正己而正物者也。正己则无我，神气不散，以正为己也。正物则无人，气质俱化，以正为物也。正己正物，内念不生，外物不入，内外一正，仁义礼智，皆本于信，金木水火，俱归于土，先天聚，后天化，性定命凝，聚正之亨利，岂小焉哉!</p><p>夫天之所以命于人者，正耳。人之所以报于天者，亦正耳。以正报天，不忘根本，如用大牲，上享于天，未有不致其吉者。然用大牲致吉之道，非空空一念便能了事，须要脚踏实地，一步步行去，方能成功。若知而不行，犹如不知，何能得吉?利有攸往，知之贵于行之耳。</p><p>初六，阴柔无断，不辨是非，或信此，或信彼，乃乱乃萃，信非所当信，聚非所当聚矣。幸应四阳，若知乱萃无益，自悔悲号，亲近真师，一经握引，暗中指点，当亦会的，道不远人，人之为道而远人。先号后笑，直下承当，不必忧恤，即时往而攒簇五行，和合四象，何患不到无咎之地哉!此改邪归正之萃也。</p><p>六二，居于三阴皆暗之中，一身纯阴，而能顺其所欲，渐次导引，化其气质之性，聚其真如之性，其利如用禴祭神，以诚感通。始而有咎者，终而可以无咎。此柔而守正之萃也。</p><p>六三，愚而自用，执着一己之阴，妄想成道，空而不实，是萃如必终嗟如，其无所利可知。幸其贤士在望，若能往而相聚，借刚济柔，亦可以免嗟如之咎。但不能聚正人于早，及至受其害而后聚，难免小吝矣。此柔而借刚之萃也。</p><p>九四，刚而能柔，阴阳相当，还丹凝结，大丹有望，不但聚之如意而大吉，必将聚于一无所咎之地矣。此凝结还丹之萃也。</p><p>九五，刚而中正，上智不移，正位凝命，无修无证，不待作为，五行一气，本自无咎。虽然无咎，嫌其居于悦体，自满自盈，信非所信，后悔必有。若知实腹而又虚心，行无为之事，温养圣胎，永于贞一，用天然真火，煅尽后天余阴，号曰无漏真人，何悔之不亡乎?此温养圣胎之萃也。</p><p>上六，愚而无知，误入旁门，以假为真，虽天宝在望，未许我聚，空空一世，临死方悔，赍咨涕洟，自致其伤，与人无咎。此始不谨而终因之萃也。</p><p>六爻各有所萃，是非邪正不同。求其阴阳相当，刚柔如一之萃，其惟九四。以虚养实，了命了性，其惟九五乎?</p><p>噫!金虾蟆，玉老鸦，认的真的是作家。</p>',26)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
